def _target_main_tree(original_tree):
    """Only two real child calls change; entire FN and module inverse hold."""
    nodes = [node for node in original_tree.body if isinstance(node, ast.FunctionDef) and node.name == MAIN_OWNER]
    if len(nodes) != 1 or _dump(nodes[0]) != _dump(ast.parse(EXPECTED_MAIN_SOURCE).body[0]):
        raise ValueError('complete current Main4AC owner required')
    original = nodes[0]
    changed = copy.deepcopy(original)
    edits = []

    class Lift(ast.NodeTransformer):
        def visit_Call(self, node):
            node = self.generic_visit(node)
            if isinstance(node.func, ast.Name) and node.func.id == '_campaign_call_fields':
                if node.keywords or len(node.args) != 4 or tuple(ast.literal_eval(value) for value in node.args[2:]) not in (POLICY_ENTRY, REFRESH_ENTRY):
                    raise ValueError('only actual Main4AC50C/512 calls are admitted')
                before = copy.deepcopy(node)
                node.func.id = '_target_campaign_call'
                after = ast.copy_location(ast.YieldFrom(value=node), node)
                edits.append((before, copy.deepcopy(after)))
                return after
            return node

    changed = Lift().visit(changed)
    if len(edits) != 2:
        raise ValueError('exactly two original Main4AC child calls required')
    pending = list(edits)

    class Inverse(ast.NodeTransformer):
        def visit_YieldFrom(self, node):
            for index, (before, after) in enumerate(pending):
                if _dump(node) == _dump(after):
                    pending.pop(index)
                    return copy.deepcopy(before)
            raise ValueError('non-admitted Main4AC continuation')

    inverse = Inverse().visit(copy.deepcopy(changed))
    if pending or _dump(inverse) != _dump(original):
        raise ValueError('complete original Main4AC FN inverse differs')
    result = copy.deepcopy(original_tree)
    index = original_tree.body.index(original)
    result.body[index] = changed
    restored = copy.deepcopy(result)
    restored.body[index] = inverse
    if _dump(restored) != _dump(original_tree):
        raise ValueError('whole original Main source-module inverse differs')
    return ast.fix_missing_locations(result)


class BattleTargetScenePrograms(BattleResultScenePrograms):
    """One actual4AC/3CE parent, reusing synchronous full-field25BD8."""

    def __init__(self, state):
        super().__init__(state)
        from ..high_level_main_flows import business_main
        self.target_module = business_main
        tree = ast.parse(inspect.getsource(business_main), filename=business_main.__file__)
        plain = compile(tree, business_main.__file__, 'exec', dont_inherit=True)
        original = getattr(business_main, MAIN_OWNER)
        if (type(original) is not FunctionType or original.__globals__ is not vars(business_main)
                or original.__module__ != business_main.__name__ or original.__name__ != MAIN_OWNER
                or original.__closure__ is not None or original.__code__.co_freevars
                or _code_shape(original.__code__) != _code_shape(_top_code(plain, MAIN_OWNER))):
            raise ValueError('actual complete unwrapped Main4AC/source owner required')
        derived = compile(_target_main_tree(tree), business_main.__file__, 'exec', dont_inherit=True)
        self.target_original, self.target_original_code = original, original.__code__
        self.target_namespace = dict(vars(business_main))
        if '_target_campaign_call' in self.target_namespace:
            raise ValueError('private target continuation must not shadow original source')
        self.target_call = self.views['main', '_campaign_call_fields']
        self.target_namespace['_target_campaign_call'] = self.target_call
        self.target_view = FunctionType(_top_code(derived, MAIN_OWNER), self.target_namespace,
            MAIN_OWNER, original.__defaults__, None)
        self.target_view.__kwdefaults__ = original.__kwdefaults__
        self.target_view.__annotations__ = dict(original.__annotations__)
        self.target_view_code = self.target_view.__code__
        if not inspect.isgeneratorfunction(self.target_view) or self.target_view.__closure__ is not None:
            raise ValueError('one complete closure-free Main4AC view required')
        self.target_reused, self.target_modules = {}, {}
        for path, sources in EXPECTED_REUSED_SOURCE.items():
            module = importlib.import_module(path)
            self.target_modules[path] = module
            current = ast.parse(inspect.getsource(module), filename=module.__file__)
            code = compile(current, module.__file__, 'exec', dont_inherit=True)
            nodes = {node.name: node for node in current.body if isinstance(node, ast.FunctionDef)}
            for name, expected in sources.items():
                owner = getattr(module, name)
                if (name not in nodes or _dump(nodes[name]) != _dump(ast.parse(expected).body[0])
                        or type(owner) is not FunctionType or owner.__globals__ is not vars(module)
                        or owner.__module__ != module.__name__ or owner.__name__ != name
                        or owner.__closure__ is not None or owner.__code__.co_freevars
                        or _code_shape(owner.__code__) != _code_shape(_top_code(code, name))):
                    raise ValueError('complete synchronous target dependency required: ' + name)
                self.target_reused[path, name] = (module, owner, owner.__code__)
        self.target_aliases = []
        for path, name, owner_path, owner_name in SOURCE_ALIASES:
            module = importlib.import_module(path)
            actual = self.target_reused[owner_path, owner_name][1]
            if getattr(module, name) is not actual:
                raise ValueError('actual mature target service alias required: ' + name)
            self.target_aliases.append((module, name, actual))

    def require_current(self, state):
        super().require_current(state)
        if not hasattr(self, 'target_original'):
            return
        if (getattr(self.target_module, MAIN_OWNER) is not self.target_original
                or self.target_original.__code__ is not self.target_original_code
                or self.target_view.__code__ is not self.target_view_code
                or self.target_namespace.get('_target_campaign_call') is not self.target_call):
            raise ValueError('actual complete Main4AC continuation owner changed')
        if hasattr(self, 'target_reused'):
            for (path, name), (module, owner, code) in self.target_reused.items():
                if getattr(module, name) is not owner or owner.__code__ is not code:
                    raise ValueError('mature target dependency changed: ' + name)
        if hasattr(self, 'target_aliases'):
            for module, name, owner in self.target_aliases:
                if getattr(module, name) is not owner:
                    raise ValueError('actual target source alias changed: ' + name)

    def _campaign_child(self, state, frame, target, continuation):
        self.require_current(state)
        if (target, continuation) == POLICY_ENTRY:
            # This already-entered helper owns50C. All nested complete-frame
            # algorithms and their physical calls stay synchronous and original.
            owner = self.target_reused['tools.high_level_main_flows.business_gameplay',
                'initialize_battle_policy_targets_frame_fields'][1]
            return owner(state, frame)
        if (target, continuation) == REFRESH_ENTRY:
            return (yield from self._refresh(SceneRefreshMemory(state), frame))
        return (yield from super()._campaign_child(state, frame, target, continuation))

    def _display_child(self, state, frame, target, continuation):
        self.require_current(state)
        if target == MAIN_TARGET:
            if continuation != 0x3CE:
                raise MovementContinuationBoundary(target, frame, 'Main4AC requires actual3CE LONG')
            return (yield from self.target_view(state, frame))
        return (yield from super()._display_child(state, frame, target, continuation))

    def main_scene_call(self, state, frame, target, continuation):
        if target != MAIN_TARGET:
            return (yield from super().main_scene_call(state, frame, target, continuation))
        self.require_current(state)
        if self._started or continuation != 0x3CE:
            raise ValueError('one actual indexed Main4AC invocation required')
        self._started = True
        return (yield from self.views['display', 'display_call_fields'](state, frame, target, continuation))
